       fmt.Println(strings.ReplaceAll(str, " ", "_"))
       // Hi,_my_dear_friend!!!

       // замена подстроки
       fmt.Println(strings.ReplaceAll(str, "dear", "good"))
       // Hi, my good friend!!!

       // удаление подстроки или символа
       fmt.Println(strings.ReplaceAll(str, "dear", ""))
       // Hi, my  friend!!!
   }
