   type SQLiteRepository struct {
       db *gorm.DB // заменили на *gorm.DB
   }

   func NewSQLiteRepository() (*SQLiteRepository, error) {
       // Создаем репозиторий
       repository := &SQLiteRepository{}

       // Проверяем существование файла базы данных
       dbExists := true
       if _, err := os.Stat(dbName); os.IsNotExist(err) {
           dbExists = false
       }

       // Открываем соединение с базой данных
       db, err := gorm.Open(sqlite.Open(dbName), &gorm.Config{
           // Отключаем вывод логов SQL-запросов. Если хотите видеть их,
           // то закомментируйте следующую строку
           Logger: logger.Default.LogMode(logger.Silent),
       })
       if err ! = nil {
           return nil, fmt.Errorf(
               "failed to connect to database: %w",
               err,
           )
       }

       // Сохраняем соединение в репозитории
       repository.db = db

       // Если база данных только что создана, выполняем миграцию
       if !dbExists {
           fmt.Println("Creating new database schema")
           if err := db.AutoMigrate(
               &Player{}, &GameSnapshot{},
               &PlayerFinishGame{},
           ); err ! = nil {
               return nil, fmt.Errorf(

