   func (r *SQLiteRepository) GetSnapshots(
       nickName string) (*[]m.GameSnapshot, error) {
       var snapshots []GameSnapshot
       // ищем игрока по никнейму
       player, err := r.getPlayer(nickName)
       if err ! = nil {
           return nil, err
       }

