       atomic.AddInt64(&a.value, 1)
   }

   func (a *AtomicCounter) Decrement() {
       atomic.AddInt64(&a.value, -1)
   }

   func (a *AtomicCounter) Value() int64 {
       return atomic.LoadInt64(&a.value)
   }

   func increment(waitGroup *sync.WaitGroup, counter *AtomicCounter) {
       counter.Increment()
       waitGroup.Done()
   }

