func fanIn(inputs ...< -chan TaskItem) < -chan TaskItem {
    var wg sync.WaitGroup
    out := make(chan TaskItem)

    wg.Add(len(inputs))

    for _, in := range inputs {
        go func(ch < -chan TaskItem) {
            for {
                value, ok := < -ch

                if !ok {
                    wg.Done()
                    break
                }

                out < - value
            }
        }(in)
    }

    go func() {
        wg.Wait()
        close(out)
    }()

    return out
}

