   Теперь перейдем к самой сложной части. Начнем с реализации метода удаления
игрока из комнаты. В этом случае необходимо проанализировать, какой это был
игрок: первый или второй; кто выступает в качестве оппонента: живой игрок или
компьютер; находится ли оппонент в игровой комнате. Возможно, это просто игрок,
который зашел в нее первым и устал ждать противника:

   func (r *Room) RemovePlayer(player p.IPlayer) {
       if r.Player1 = = player {
           r.Player1 = nil // Удаляем первого игрока
           // Если в комнате есть второй игрок и он человек,
           // уведомляем его о выходе соперника
           if r.Player2 ! = nil && !r.Player2.IsComputer() {
               opponentLeft := &n.OpponentLeft{
                   // Имя вышедшего игрока
                   Nickname: player.GetNickname(),
               }
               payloadBytes, err := json.Marshal(opponentLeft)
               if err ! = nil {
                   log.Printf("Error marshaling OpponentLeft: %v", err)
                   return
               }
               msg := &n.Message{
                   Cmd:     n.CmdOpponentLeft, // Команда "соперник вышел"
                   Payload: payloadBytes,
               }
               // Отправляем сообщение второму игроку
               r.Player2.SendMessage(msg)
           }
       } else if r.Player2 = = player {
           r.Player2 = nil // Удаляем второго игрока
           // Если в комнате есть первый игрок,
           // уведомляем его о выходе соперника
           if r.Player1 ! = nil {
               opponentLeft := &n.OpponentLeft{
                   Nickname: player.GetNickname(),
               }
               payloadBytes, err := json.Marshal(opponentLeft)
               if err ! = nil {
                   log.Printf("Error marshaling OpponentLeft: %v", err)
                   return
               }
               msg := &n.Message{
                   Cmd:     n.CmdOpponentLeft,
                   Payload: payloadBytes,
               }
               // Отправляем сообщение первому игроку
               r.Player1.SendMessage(msg)
           }
       }
   }
  Следующий метод будет отвечать за начальную инициализацию новой игры
в комнате. В ходе этого процесса мы должны убедиться, что в комнате достаточно
игроков для начала игры (не менее двух), затем случайным образом определить, кто
делает ход первым (Х или О), после чего обновить состояние комнаты и текущего
игрока в зависимости от выбранного режима (PvC или PvP). Далее формируем
сообщение о том, что игра начинается, каково актуальное состояние доски и кто

