делает ход первым, и отправляем его обоим игрокам. Если первым ходит компьютер,
то он сразу (автоматически) сделает свой ход:

   func (r *Room) InitGame() {
       if !r.IsFull() {
           return // Если игроков меньше двух, игра не начинается
       }

       // Срез для определения игрока, ходящего первым
       randomPlayer := []b.BoardField{b.Cross, b.Nought}
       if !r.Board.IsEmpty() {
           // Если доска не пустая, создаем новую
