               now := time.Now()
               // Если прошло более 3 секунд с момента последнего сообщения
               if now.Sub(c.lastMsgTime) > 3*time.Second {
                   c.lastMsgTime = now
                   fmt.Println("\nWaiting for opponent to join...")
                   fmt.Println("Press 'q' and Enter to return to main menu")
                   fmt.Print("> ")
               }

               // Проверяем ввод пользователя
               var buffer [1]byte
               n, _ := os.Stdin.Read(buffer[:])
               // Если пользователь нажал 'q' или 'Q',
               // то выходим в главное меню
               if n > 0 && (buffer[0] = = 'q' || buffer[0] = = 'Q') {
                   fmt.Println("Leaving room...")
                   // Формируем сообщение о выходе из комнаты
                   // и отправляем на сервер
                   var msg network.Message
                   msg.Cmd = network.CmdLeaveRoomRequest
                   payload := network.LeaveRoomRequest{
                       RoomName:   c.roomName,
                       PlayerName: c.playerName,
                   }
                   jsonPayload, _ := json.Marshal(payload)
                   msg.Payload = jsonPayload
                   encoder.Encode(msg)  // Отправляем сообщение на сервер
                   c.setState(mainMenu) // Переходим в главное меню
                   continue
               }

               // Небольшое время сна для избежания загрузки процессора
               time.Sleep(100 * time.Millisecond)
               continue
           }
       }
   }
   Вернемся к файлу client.go и объединим весь написанный ранее функционал
клиентского приложения, добавив два метода. Первый будет отвечать за старт
работы с сервером, а второй — за маршрутизацию принятых сообщений по их об
работчикам в отдельной горутине:

   // baseURL/part_8/tic_tac_toe_v7/client/client.go
   // Запускаем клиент
   func (c *Client) Start() {
       defer c.conn.Close()

       fmt.Println("Connected to server. ")
       // Запускаем горутину для чтения сообщений от сервера
       go c.readFromServer()
       // Запускаем управление пользовательским потоком
       c.handleUserFlow()
   }

502       Глава 8   Сетевое программирование

   func (c *Client) readFromServer() { // Читаем сообщения от сервера
       decoder := json.NewDecoder(c.conn) // Создаем декодер
       for {   // Бесконечный цикл
           // Создаем буфер и десериализуем в него сообщение от сервера
           var msg network.Message
           if err := decoder.Decode(&msg); err ! = nil {
               log.Printf("Disconnected from server: %v", err)
               return // если соединение потеряно — выходим из горутины
           }

           switch msg.Cmd {
           // Обрабатываем ответ на запрос о присоединении к комнате
           case network.CmdRoomJoinResponse:
               c.handleRoomJoinResponse(msg.Payload)
           // Обрабатываем сообщение об инициализации игры
           case network.CmdInitGame:
               c.handleInitGame(msg.Payload)
           // Обрабатываем сообщение об обновлении состояния игры
           case network.CmdUpdateState:
               c.handleUpdateState(msg.Payload)
           // Обрабатываем сообщение об окончании игры
           case network.CmdEndGame:
               c.handleEndGame(msg.Payload)
           // Обрабатываем сообщение об ошибке
           case network.CmdError:
               c.handleError(msg.Payload)
           // Обрабатываем сообщение о списке комнат
           case network.CmdRoomListResponse:
               c.handleRoomListResponse(msg.Payload)
           // Обрабатываем сообщение о подтверждении никнейма
           case network.CmdNickNameResponse:
               c.handleNickNameResponse(msg.Payload)
           // Обрабатываем сообщение об отключении оппонента
           case network.CmdOpponentLeft:
               c.handleOpponentLeft(msg.Payload)
           // Обрабатываем сообщение о списке завершенных игр
           case network.CmdFinishedGamesResponse:
               c.handleFinishedGamesResponse(msg.Payload)
           // Обрабатываем сообщение с данными
           // о запрошенной завершенной игре
           case network.CmdFinishedGameResponse:
               c.handleFinishedGameResponse(msg.Payload)
           default: // Если пришло неизвестное сообщение
               log.Printf(
                   "Received unhandled message type '%s' "+
                       "from server. Payload: %s\n> ",
                   msg.Cmd, string(msg.Payload),
               )
           }
       }
   }
  На этой высокой ноте мы завершаем работу над клиентской частью приложения.

Запуск игры
Настало время добавить в функцию main одноименного пакета код, который, в за
висимости от передаваемых флагов и их параметров, будет запускать серверное либо
клиентское приложение. Откройте файл main.go и добавьте в него следующий код:

Проект: игра «Крестики-нолики», v.7      503

   // baseURL/part_8/tic_tac_toe_v7/main.go
   package main

   import (
       "flag"
       "log"

       "tic-tac-toe/client"
       "tic-tac-toe/database"
       "tic-tac-toe/server"
   )

   func main() {
       // Флаг для выбора режима работы
       mode := flag.String(
           "mode", "server",
           "start in 'server' or 'client' mode",
       )
       // Флаг для указания адреса
       // :8088 = 127.0.0.1:8088 или localhost:8088
       addr := flag.String("addr", ":8088", "address to run on")
       flag.Parse() // Парсим флаги

       switch *mode { // Переключение режима работы
       case "server": // Режим сервера
           // Создаем репозиторий
           repository, err := database.NewSQLiteRepository()
           if err ! = nil {
               log.Fatalf("Failed to create repository: %v", err)
           }
           // Создаем сервер и запускаем его, передав
           // ему адрес в формате "ip:port" и репозиторий
           srv, err := server.NewServer(*addr, repository)
           if err ! = nil {
               log.Fatalf("Failed to create server: %v", err)
           }
           srv.Start() // запускаем сервер
       case "client": // Режим клиента
           // Создаем клиент и запускаем его, передав
           // ему адрес сервера в формате "ip:port"
           cli, err := client.NewClient(*addr)
           if err ! = nil {
               log.Fatalf("Failed to connect to server: %v", err)
           }
           cli.Start() // запускаем клиентское приложение
       default: // Неизвестный режим
           log.Fatalf(
               "Unknown mode: %s. Use 'server' or 'client'.", *mode,
           )
       }
   }
   Теперь откройте терминал в VS Code в сплит-режиме, который разделяет окно
надвое. В левой части запустите сервер, введя команду:

